/**
 * Human wording for run and node states. The wording deliberately separates "this node finished" from
 * "this workflow is complete": only a `succeeded` run is complete, and a worker node's success only means
 * its native session launched and ended its turn.
 */
import { isBlockingFinding, type ReviewResult, type RunDetail } from './api.ts'

export type RunStatus = RunDetail['summary']['status']
export type NodeKind = RunDetail['definition']['nodes'][number]['kind']

export const STATUS_LABEL: Record<RunStatus, string> = {
  pending: 'Pending',
  running: 'Running',
  awaiting_approval: 'Awaiting approval',
  paused: 'Paused',
  succeeded: 'Succeeded',
  failed: 'Failed',
  cancelled: 'Cancelled',
}

/** What a run in this status means for the workflow as a whole. */
export const RUN_STATUS_MEANING: Record<RunStatus, string> = {
  pending: 'Nothing has started yet.',
  running: 'Work is in progress. The workflow is not complete.',
  awaiting_approval: 'Stopped at a decision that has not been made. The workflow is not complete; nothing is approved by viewing it.',
  paused: 'Paused with unresolved state (for example a session that could not be reconciled). The workflow is not complete.',
  succeeded: 'Integration was confirmed and no graph work remains.',
  failed: 'A graph step or check failed. The workflow did not complete.',
  cancelled: 'The run was cancelled before completion.',
}

/** What a node in this status means, given its kind. */
export function nodeStatusMeaning(kind: NodeKind, status: RunStatus): string {
  switch (status) {
    case 'pending': return 'Not started: no attempt has run.'
    case 'running': return kind === 'worker' ? 'The native worker session is running or its turn has not been signalled complete.' : 'In progress.'
    case 'awaiting_approval': return 'Waiting for an explicit decision recorded outside this viewer. Not complete.'
    case 'paused': return 'Paused with unresolved evidence. Not complete.'
    case 'succeeded':
      return kind === 'worker'
        ? 'The worker session launched and ended its turn. This is not workflow completion; verification, review and integration are separate nodes.'
        : kind === 'integration'
          ? 'This integration step completed.'
          : 'This step completed.'
    case 'failed': return 'This step failed. The run cannot succeed without intervention.'
    case 'cancelled': return 'This step was cancelled.'
  }
}

export const KIND_LABEL: Record<NodeKind, string> = {
  prepare: 'Preparation',
  worker: 'Worker',
  verification: 'Verification',
  review: 'Review',
  integration: 'Integration',
}

/**
 * Who executes a node, derived from its kind (PRD_VIEWER_CLARITY 4.3): a worker is an agent session, a review is one
 * agent session per reviewer (one print job per reviewer when the review ran with the print transport), a
 * verification is the trusted verifier, and preparation and integration are the controller itself.
 */
export type Executor = 'agent' | 'verifier' | 'controller'

export const EXECUTOR_LABEL: Record<NodeKind, string> = {
  prepare: 'controller',
  worker: 'agent session',
  verification: 'trusted verifier',
  review: 'one agent session per reviewer',
  integration: 'controller',
}

/** The executor category of a node kind: agents are drawn solid, the verifier and the controller dashed. */
export function executorCategory(kind: NodeKind): Executor {
  if (kind === 'worker' || kind === 'review') return 'agent'
  return kind === 'verification' ? 'verifier' : 'controller'
}

/** The design challenge node of a guarded run (PRD_PORTABLE_WORKFLOW 4.5): kind `review`, but not the independent review. */
export const CHALLENGE_NODE_ID = 'challenge'

export function isChallengeNode(node: { node_id: string; kind: NodeKind }): boolean {
  return node.node_id === CHALLENGE_NODE_ID && node.kind === 'review'
}

/**
 * The executor wording for a node; a review names print jobs when the served review result's transport is `print`, and
 * the design challenge is always one print job.
 */
export function executorOf(kind: NodeKind, transport?: ReviewResult['reviewer']['transport'], nodeId?: string): string {
  if (nodeId !== undefined && isChallengeNode({ node_id: nodeId, kind })) return 'one print job'
  if (kind === 'review' && transport === 'print') return 'one print job per reviewer'
  return EXECUTOR_LABEL[kind]
}

export function shortRevision(revision: string): string {
  return revision.slice(0, 12)
}

export function formatTime(iso: string): string {
  const time = Date.parse(iso)
  if (Number.isNaN(time)) return iso
  return new Date(time).toISOString().replace('T', ' ').replace(/\.\d{3}Z$/, ' UTC')
}

/** Compact duration for deadlines and timeouts: 14400 → "4h", 5400 → "1h30m", 45 → "45s". */
export function formatDuration(seconds: number): string {
  const hours = Math.floor(seconds / 3600)
  const minutes = Math.floor((seconds % 3600) / 60)
  const rest = seconds % 60
  const parts: string[] = []
  if (hours > 0) parts.push(`${hours}h`)
  if (minutes > 0) parts.push(`${minutes}m`)
  if (rest > 0 || parts.length === 0) parts.push(`${rest}s`)
  return parts.join('')
}

/** The automatic profile's deadlines as one phrase, e.g. "worker 4h · review 30m". */
export function deadlinesLabel(automatic: { worker_timeout_seconds: number; review_timeout_seconds: number }): string {
  return `worker ${formatDuration(automatic.worker_timeout_seconds)} · review ${formatDuration(automatic.review_timeout_seconds)}`
}

const DISPOSITIONS = ['open', 'resolved', 'accepted'] as const

/** One line for a recorded review: verdict, finding counts by disposition and how many block integration (unresolved P0/P1). */
export function reviewSummary(review: ReviewResult): string {
  const { verdict, findings } = review
  if (findings.length === 0) return `${verdict} with no findings`
  const counts = DISPOSITIONS
    .map(disposition => [disposition, findings.filter(finding => finding.disposition === disposition).length] as const)
    .filter(([, count]) => count > 0)
    .map(([disposition, count]) => `${count} ${disposition}`)
  const blocking = findings.filter(isBlockingFinding).length
  return `${verdict} with ${findings.length} ${findings.length === 1 ? 'finding' : 'findings'}: ${counts.join(', ')}, ${blocking === 0 ? 'none blocking' : `${blocking} blocking`}`
}
import { useCallback, useEffect, useRef, useState } from 'react'

export type Resource<T> =
  | { status: 'idle' }
  | { status: 'loading' }
  | { status: 'ready'; data: T }
  | { status: 'error'; error: unknown }

/**
 * Loads one read-only resource identified by `key`. A null key means nothing to load. Changing the key or
 * calling `reload` starts a fresh request and abandons the previous one; a stale response never wins
 * because every settled value is tagged with the request token that produced it.
 * `refreshToken` forces a reload without changing the key (the header Refresh button).
 * `pollToken` reloads in the background (live polling): the last settled value stays shown while it loads, and a
 * failed poll keeps the last loaded data instead of replacing it with an error.
 */
export function useResource<T>(key: string | null, load: (signal: AbortSignal) => Promise<T>, refreshToken = 0, pollToken = 0): { state: Resource<T>; reload: () => void } {
  const [settled, setSettled] = useState<{ base: string; token: string; value: Resource<T> } | null>(null)
  const [attempt, setAttempt] = useState(0)
  const loadRef = useRef(load)
  useEffect(() => { loadRef.current = load }, [load])
  const base = key === null ? null : `${key}\u0000${attempt}\u0000${refreshToken}`
  const token = base === null ? null : `${base}\u0000${pollToken}`

  useEffect(() => {
    if (token === null || base === null) return
    const controller = new AbortController()
    loadRef.current(controller.signal).then(
      data => { if (!controller.signal.aborted) setSettled({ base, token, value: { status: 'ready', data } }) },
      error => {
        if (controller.signal.aborted) return
        setSettled(previous => previous !== null && previous.base === base && previous.value.status === 'ready'
          ? { ...previous, token }
          : { base, token, value: { status: 'error', error } })
      },
    )
    return () => controller.abort()
  }, [base, token])

  const reload = useCallback(() => setAttempt(previous => previous + 1), [])
  const state: Resource<T> = token === null ? { status: 'idle' } : settled !== null && settled.base === base ? settled.value : { status: 'loading' }
  return { state, reload }
}
import { useEffect, useState } from 'react'

/** How often a live Projects page re-reads its run state. */
export const POLL_INTERVAL_MS = 5000

/**
 * A counter that ticks every `intervalMs` while `active` and the page is visible, and once more as the page becomes
 * visible again; pass it as a resource's `pollToken` to re-read live state in the background.
 */
export function usePoll(active: boolean, intervalMs = POLL_INTERVAL_MS): number {
  const [tick, setTick] = useState(0)
  useEffect(() => {
    if (!active) return
    const next = () => { if (document.visibilityState === 'visible') setTick(previous => previous + 1) }
    const timer = window.setInterval(next, intervalMs)
    document.addEventListener('visibilitychange', next)
    return () => {
      window.clearInterval(timer)
      document.removeEventListener('visibilitychange', next)
    }
  }, [active, intervalMs])
  return tick
}
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Breadcrumbs, type PathCrumb } from '../graph/Breadcrumbs.tsx'
import { fetchProjects, fetchRunDetail, fetchRuns, fetchWorkflows, ProjectsApiError, type RunPage, type RunSummary } from './api.ts'
import { AppLink, EmptyPanel, ErrorPanel, LoadingPanel, StatusBadge } from './panels.tsx'
import { projectPathname, projectsPathname, runPathname, workflowPathname, type ProjectsRoute } from './routes.ts'
import { RunView } from './RunView.tsx'
import { formatTime, shortRevision } from './status.ts'
import { usePoll } from './usePoll.ts'
import { useResource } from './useResource.ts'
import { WorkflowGraph } from './WorkflowGraph.tsx'

type Props = {
  /** Null when the pathname is under /projects but malformed. */
  route: ProjectsRoute | null
  refreshToken: number
  onNavigate: (pathname: string) => void
  onAnnounce: (message: string) => void
}

/**
 * The Projects root: registered projects, their workflow definitions and runs, read-only. Every level
 * loads from the scoped API and shows loading, empty, not-found and failure states in place; nothing
 * is ever substituted from fixtures.
 */
export function ProjectsView({ route, refreshToken, onNavigate, onAnnounce }: Props) {
  const projectId = route && route.level !== 'projects' ? route.projectId : null
  const workflowId = route && (route.level === 'workflow' || route.level === 'run') ? route.workflowId : null
  const runId = route && route.level === 'run' ? route.runId : null
  const nodeId = route && route.level === 'run' ? route.nodeId : null

  // The registry itself changes while the viewer runs (a launch registers its workflow); both lists are cheap to re-read.
  const registryPoll = usePoll(route?.level === 'projects' || route?.level === 'project')
  const { state: projects, reload: reloadProjects } = useResource('projects', fetchProjects, refreshToken, registryPoll)
  const loadWorkflows = useCallback((signal: AbortSignal) => fetchWorkflows(projectId!, signal), [projectId])
  const { state: workflows, reload: reloadWorkflows } = useResource(projectId === null ? null : `workflows:${projectId}`, loadWorkflows, refreshToken, registryPoll)
  const loadRuns = useCallback((signal: AbortSignal) => fetchRuns(projectId!, workflowId!, {}, signal), [projectId, workflowId])
  const runsKey = workflowId === null ? null : `runs:${projectId}/${workflowId}`
  // Run lists and run details re-read themselves while shown (a finished run no longer changes). A list stops polling
  // while it loads or shows appended pages, since a new first page would drop them.
  const [morePages, setMorePages] = useState<{ base: RunPage | null; pages: RunPage[]; loading: boolean; error: unknown }>({ base: null, pages: [], loading: false, error: null })
  const [finished, setFinished] = useState(false)
  // Appended pages belong to one list generation (this workflow, this Refresh); a new one starts without them.
  const listGeneration = `${runsKey}\u0000${refreshToken}`
  useEffect(() => { setMorePages({ base: null, pages: [], loading: false, error: null }) }, [listGeneration])
  const listPoll = usePoll(route?.level === 'workflow' && !morePages.loading && morePages.pages.length === 0)
  const runPoll = usePoll(route?.level === 'run' && !finished)
  const { state: firstPage, reload: reloadRuns } = useResource(runsKey, loadRuns, refreshToken, listPoll)
  const scope = useMemo(() => (projectId === null || workflowId === null || runId === null ? null : { projectId, workflowId, runId }), [projectId, workflowId, runId])
  const loadDetail = useCallback((signal: AbortSignal) => fetchRunDetail({ projectId: projectId!, workflowId: workflowId!, runId: runId! }, signal), [projectId, workflowId, runId])
  const { state: detail, reload: reloadDetail } = useResource(scope === null ? null : `run:${scope.projectId}/${scope.workflowId}/${scope.runId}`, loadDetail, refreshToken, runPoll)
  const detailStatus = detail.status === 'ready' ? detail.data.summary.status : null
  useEffect(() => { setFinished(detailStatus === 'succeeded' || detailStatus === 'cancelled') }, [detailStatus])

  // Additional run pages are appended on demand; they belong to exactly one loaded first page and are dropped with it.
  const firstPageData = firstPage.status === 'ready' ? firstPage.data : null
  const extra = morePages.base !== null && morePages.base === firstPageData ? morePages : { base: firstPageData, pages: [], loading: false, error: null }
  const pages: RunPage[] = firstPageData ? [firstPageData, ...extra.pages] : []
  const runs: RunSummary[] = pages.flatMap(page => page.runs)
  const nextCursor = pages.length ? pages[pages.length - 1].nextCursor : null
  const loadMore = async () => {
    if (!nextCursor || projectId === null || workflowId === null || firstPageData === null) return
    setMorePages({ ...extra, base: firstPageData, loading: true, error: null })
    try {
      const page = await fetchRuns(projectId, workflowId, { cursor: nextCursor })
      setMorePages(previous => (previous.base === firstPageData ? { ...previous, pages: [...previous.pages, page], loading: false } : previous))
    } catch (error) {
      setMorePages(previous => (previous.base === firstPageData ? { ...previous, loading: false, error } : previous))
    }
  }

  const projectName = projects.status === 'ready' && projectId !== null ? projects.data.find(project => project.project_id === projectId)?.name ?? projectId : projectId
  const currentWorkflow = workflows.status === 'ready' && workflowId !== null ? workflows.data.find(workflow => workflow.workflow_id === workflowId) ?? null : null
  const workflowName = currentWorkflow?.name ?? workflowId

  // A background poll re-announces only what changed; a load the reader started (navigation, Refresh) always announces.
  const announced = useRef<string | null>(null)
  useEffect(() => {
    let message: string | null = null
    if (route === null) message = 'This Projects link is invalid.'
    else if (route.level === 'projects' && projects.status === 'ready') message = `Loaded ${projects.data.length} ${projects.data.length === 1 ? 'project' : 'projects'}.`
    else if (route.level === 'project' && workflows.status === 'ready') message = `Loaded ${workflows.data.length} ${workflows.data.length === 1 ? 'workflow' : 'workflows'} for ${projectName ?? route.projectId}.`
    else if (route.level === 'workflow' && firstPage.status === 'ready') message = `Loaded ${firstPage.data.runs.length} ${firstPage.data.runs.length === 1 ? 'run' : 'runs'} for ${workflowName ?? route.workflowId}.`
    else if (route.level === 'run' && detail.status === 'ready') message = `Loaded run ${route.runId}: ${detail.data.summary.status.replace('_', ' ')}.`
    else if ((projects.status === 'error') || workflows.status === 'error' || firstPage.status === 'error' || detail.status === 'error') message = 'Loading failed.'
    if (message === null) { announced.current = null; return }
    if (message === announced.current) return
    announced.current = message
    onAnnounce(message)
  }, [route, projects, workflows, firstPage, detail, projectName, workflowName, onAnnounce])

  const crumbs: PathCrumb[] = [{ id: 'home', label: 'Home', pathname: '/' }, { id: 'projects', label: 'Projects', pathname: projectsPathname() }]
  if (projectId !== null) crumbs.push({ id: `project:${projectId}`, label: projectName ?? projectId, pathname: projectPathname(projectId) })
  if (projectId !== null && workflowId !== null) crumbs.push({ id: `workflow:${workflowId}`, label: workflowName ?? workflowId, pathname: workflowPathname(projectId, workflowId) })
  if (projectId !== null && workflowId !== null && runId !== null) crumbs.push({ id: `run:${runId}`, label: runId, pathname: runPathname(projectId, workflowId, runId) })
  if (route === null) crumbs.push({ id: 'invalid', label: 'Invalid link' })

  const notFound = (error: unknown) => error instanceof ProjectsApiError && error.notFound

  let info: string
  if (route === null) info = 'This Projects link is invalid.'
  else if (route.level === 'projects') info = 'Registered projects. Read-only: runs are started, approved and retried from the workflow CLI, never from this page.'
  else if (route.level === 'project') info = 'Workflow definitions registered for this project.'
  else if (route.level === 'workflow') info = 'Runs of this workflow, newest first. Each run keeps the definition it was started with.'
  else info = nodeId === null ? 'Run detail with its pinned definition graph.' : `Run detail, inspecting node ${nodeId}.`

  const busy = projects.status === 'loading' || workflows.status === 'loading' || firstPage.status === 'loading' || detail.status === 'loading'

  let content: React.ReactNode
  if (route === null) {
    content = (
      <div className="projects-error" role="alert">
        <p>This Projects link is invalid and could not be read. Links look like /projects/&lt;project&gt;/workflows/&lt;workflow&gt;/runs/&lt;run&gt;.</p>
        <p className="projects-actions"><AppLink href={projectsPathname()} onNavigate={onNavigate}>Go to Projects</AppLink></p>
      </div>
    )
  } else if (route.level === 'projects') {
    if (projects.status === 'loading' || projects.status === 'idle') content = <LoadingPanel>Loading registered projects…</LoadingPanel>
    else if (projects.status === 'error') content = <ErrorPanel error={projects.error} what="The project list" onRetry={reloadProjects} />
    else if (projects.data.length === 0) {
      content = (
        <EmptyPanel title="No projects are registered." testId="empty-projects">
          <p>The backend's project registry is empty. Projects are registered by the operator in the server configuration, not from this page.</p>
        </EmptyPanel>
      )
    } else {
      content = (
        <section aria-labelledby="projects-title">
          <h2 id="projects-title">Projects</h2>
          <ul className="projects-list" data-testid="projects-list">
            {projects.data.map(project => (
              <li key={project.project_id}>
                <AppLink href={projectPathname(project.project_id)} onNavigate={onNavigate} className="projects-card">
                  <span className="projects-card-title">{project.name}</span>
                  <span className="projects-muted">{project.project_id}</span>
                </AppLink>
              </li>
            ))}
          </ul>
        </section>
      )
    }
  } else if (route.level === 'project') {
    if (workflows.status === 'loading' || workflows.status === 'idle') content = <LoadingPanel>Loading workflows of {projectName}…</LoadingPanel>
    else if (workflows.status === 'error' && notFound(workflows.error)) {
      content = (
        <div className="projects-error" role="alert" data-testid="not-found">
          <p><strong>Project “{route.projectId}” is not registered.</strong> The API has no project with this ID; it may have been removed from the registry or the link may be wrong.</p>
          <p className="projects-actions"><AppLink href={projectsPathname()} onNavigate={onNavigate}>Go to Projects</AppLink></p>
        </div>
      )
    } else if (workflows.status === 'error') content = <ErrorPanel error={workflows.error} what={`The workflows of ${projectName}`} onRetry={reloadWorkflows} />
    else if (workflows.data.length === 0) {
      content = (
        <EmptyPanel title={`${projectName} has no workflow definitions.`} testId="empty-workflows">
          <p>The project is registered but no workflow is configured for it, so there is nothing to run or inspect here.</p>
        </EmptyPanel>
      )
    } else {
      content = (
        <section aria-labelledby="workflows-title">
          <h2 id="workflows-title">{projectName}: workflows</h2>
          <ul className="projects-list" data-testid="workflows-list">
            {workflows.data.map(workflow => (
              <li key={workflow.workflow_id}>
                <AppLink href={workflowPathname(route.projectId, workflow.workflow_id)} onNavigate={onNavigate} className="projects-card">
                  <span className="projects-card-title">{workflow.name}</span>
                  <span className="projects-muted">{workflow.workflow_id} · {workflow.nodes.length} {workflow.nodes.length === 1 ? 'node' : 'nodes'} · current revision {shortRevision(workflow.definition_revision)}</span>
                </AppLink>
              </li>
            ))}
          </ul>
        </section>
      )
    }
  } else if (route.level === 'workflow') {
    if (firstPage.status === 'loading' || firstPage.status === 'idle') content = <LoadingPanel>Loading runs of {workflowName}…</LoadingPanel>
    else if (firstPage.status === 'error' && notFound(firstPage.error)) {
      content = (
        <div className="projects-error" role="alert" data-testid="not-found">
          <p><strong>Workflow “{route.workflowId}” was not found in project “{route.projectId}”.</strong> Either the project is not registered or this workflow does not belong to it.</p>
          <p className="projects-actions">
            <AppLink href={projectPathname(route.projectId)} onNavigate={onNavigate}>Go to the project</AppLink>
            <AppLink href={projectsPathname()} onNavigate={onNavigate}>Go to Projects</AppLink>
          </p>
        </div>
      )
    } else if (firstPage.status === 'error') content = <ErrorPanel error={firstPage.error} what={`The runs of ${workflowName}`} onRetry={reloadRuns} />
    else {
      content = (
        <div className="workflow-view">
          <section aria-labelledby="runs-title">
            <h2 id="runs-title">{workflowName}: runs</h2>
            {runs.length === 0 ? (
              <EmptyPanel title="No runs have been recorded for this workflow." testId="empty-runs">
                <p>The workflow definition exists (see its current graph below) but it has never been run, or its runs are stored elsewhere. Runs are started from the workflow CLI.</p>
              </EmptyPanel>
            ) : (
              <ul className="projects-list run-list" data-testid="run-list">
                {runs.map(run => (
                  <li key={run.run_id} data-run-id={run.run_id} data-status={run.status}>
                    <AppLink href={runPathname(route.projectId, route.workflowId, run.run_id)} onNavigate={onNavigate} className="projects-card">
                      <span className="projects-card-title">{run.run_id} <StatusBadge status={run.status} explain /></span>
                      <span className="projects-muted">updated {formatTime(run.updated_at)} · created {formatTime(run.created_at)} · pinned revision {shortRevision(run.definition_revision)}</span>
                    </AppLink>
                  </li>
                ))}
              </ul>
            )}
            {nextCursor && (
              <div className="projects-actions">
                <button type="button" className="button" onClick={() => void loadMore()} disabled={extra.loading} aria-busy={extra.loading}>
                  {extra.loading ? 'Loading more runs…' : 'Load more runs'}
                </button>
              </div>
            )}
            {extra.error !== null && <ErrorPanel error={extra.error} what="The next page of runs" onRetry={() => void loadMore()} />}
          </section>
          <section aria-labelledby="definition-title" className="workflow-definition">
            <h3 id="definition-title">Current definition</h3>
            {workflows.status === 'loading' && <LoadingPanel>Loading the current definition…</LoadingPanel>}
            {workflows.status === 'error' && <ErrorPanel error={workflows.error} what="The current definition" onRetry={reloadWorkflows} />}
            {workflows.status === 'ready' && currentWorkflow === null && <p className="projects-error-inline" role="alert">The workflow list does not contain “{route.workflowId}”, so its current definition cannot be shown.</p>}
            {currentWorkflow && (
              <>
                <p className="projects-muted" data-testid="current-definition">{currentWorkflow.name} · revision <code>{shortRevision(currentWorkflow.definition_revision)}</code> · {currentWorkflow.nodes.length} nodes. Runs started before a definition change keep their own pinned graph.</p>
                <WorkflowGraph title={`Current definition graph of ${currentWorkflow.name}`} nodes={currentWorkflow.nodes} selectedId={null} />
              </>
            )}
          </section>
        </div>
      )
    }
  } else {
    const loading = detail.status === 'loading' || detail.status === 'idle'
    if (loading) content = <LoadingPanel>Loading run {route.runId}…</LoadingPanel>
    else if (detail.status === 'error' && notFound(detail.error)) {
      content = (
        <div className="projects-error" role="alert" data-testid="not-found">
          <p><strong>Run “{route.runId}” was not found in workflow “{route.workflowId}” of project “{route.projectId}”.</strong> Runs are only served under the project and workflow they belong to; a run of another project is not shown here.</p>
          <p className="projects-actions">
            <AppLink href={workflowPathname(route.projectId, route.workflowId)} onNavigate={onNavigate}>Go to the workflow's runs</AppLink>
            <AppLink href={projectsPathname()} onNavigate={onNavigate}>Go to Projects</AppLink>
          </p>
        </div>
      )
    } else if (detail.status === 'error') content = <ErrorPanel error={detail.error} what={`Run ${route.runId}`} onRetry={reloadDetail} />
    else content = <RunView scope={scope!} detail={detail.data} current={currentWorkflow} selectedNodeId={nodeId} refreshToken={refreshToken} pollToken={runPoll} onNavigate={onNavigate} />
  }

  return (
    <>
      <div className="navigation">
        <Breadcrumbs custom={{ crumbs, onNavigate }} selected={null} index={null} onNavigate={() => undefined} />
        <p className="folder-info" data-testid="projects-info">{info}</p>
      </div>
      <main className="workspace workspace-projects" aria-busy={busy} data-testid="projects-workspace">
        {content}
      </main>
    </>
  )
}

import { useCallback, useState, type KeyboardEvent } from 'react'
import { fetchEvents, fetchRunInputs, NOT_RECORDED, orNotRecorded, type RunDetail, type RunScope, type WorkflowDefinition } from './api.ts'
import { AssignmentPanel, INPUTS_NONE_SENTENCE } from './Assignment.tsx'
import { NodeDetail } from './NodeDetail.tsx'
import { AppLink, ErrorPanel, LoadingPanel, StatusBadge } from './panels.tsx'
import { runPathname } from './routes.ts'
import { deadlinesLabel, formatTime, KIND_LABEL, RUN_STATUS_MEANING, shortRevision, STATUS_LABEL } from './status.ts'
import { useResource } from './useResource.ts'
import { WorkflowGraph, type GraphNodeView } from './WorkflowGraph.tsx'

type Props = {
  scope: RunScope
  detail: RunDetail
  /** The workflow's current definition, when the workflow list loaded; used only to say whether it changed. */
  current: WorkflowDefinition | null
  selectedNodeId: string | null
  refreshToken: number
  /** Ticks while the run page polls live state; the run's events and inputs re-read in the background with it. */
  pollToken?: number
  onNavigate: (pathname: string) => void
}

type Tab = 'run' | 'assignment'
type Highlight = { nodeId: string; quote: string }
type FileFocus = { nodeId: string; path: string }

const TABS: { id: Tab; label: string; testId: string }[] = [
  { id: 'run', label: 'Run', testId: 'tab-run' },
  { id: 'assignment', label: 'Assignment', testId: 'tab-assignment' },
]

/** One run: its summary and pinned inputs, its definition graph coloured by actual node statuses, the selected node, and the assignment. */
export function RunView({ scope, detail, current, selectedNodeId, refreshToken, pollToken = 0, onNavigate }: Props) {
  const { summary, definition, snapshot } = detail
  const snapshotById = new Map(snapshot.nodes.map(node => [node.node_id, node]))
  const graphNodes: GraphNodeView[] = definition.nodes.map(node => {
    const state = snapshotById.get(node.node_id)!
    return { node_id: node.node_id, label: node.label, kind: node.kind, depends_on: node.depends_on, status: state.status, attempt: state.attempt }
  })
  const selectedDefinition = selectedNodeId === null ? null : definition.nodes.find(node => node.node_id === selectedNodeId) ?? null
  const selectedState = selectedNodeId === null ? null : snapshotById.get(selectedNodeId) ?? null

  const runKey = `${scope.projectId}/${scope.workflowId}/${scope.runId}`
  const loadEvents = useCallback((signal: AbortSignal) => fetchEvents(scope, signal), [scope])
  const { state: events, reload: reloadEvents } = useResource(`events:${runKey}`, loadEvents, refreshToken, pollToken)
  // The inputs are one resource per run; a 404 INPUTS_NOT_FOUND means "not recorded", which loads as null.
  const loadInputs = useCallback((signal: AbortSignal) => orNotRecorded(fetchRunInputs(scope, signal), NOT_RECORDED.inputs), [scope])
  const { state: inputs, reload: reloadInputs } = useResource(`inputs:${runKey}`, loadInputs, refreshToken, pollToken)

  const [tab, setTab] = useState<Tab>('run')
  // A requirement quote handed from a review finding to a worker's task; it applies to one node and is dropped once applied or when leaving it.
  const [pendingHighlight, setPendingHighlight] = useState<Highlight | null>(null)
  const clearHighlight = useCallback(() => setPendingHighlight(null), [])
  const highlight = pendingHighlight !== null && pendingHighlight.nodeId === selectedNodeId ? pendingHighlight.quote : null
  // A captured file handed from a review finding to the launch node that shows it, applied the same way.
  const [pendingFile, setPendingFile] = useState<FileFocus | null>(null)
  const clearFile = useCallback(() => setPendingFile(null), [])
  const fileFocus = pendingFile !== null && pendingFile.nodeId === selectedNodeId ? pendingFile.path : null

  const nodePathname = (nodeId: string | null = null) => runPathname(scope.projectId, scope.workflowId, scope.runId, nodeId)
  const selectNode = (nodeId: string) => onNavigate(nodePathname(nodeId))
  const navigateToNode = (pathname: string) => {
    setTab('run')
    onNavigate(pathname)
  }
  const openRequirement = useCallback((nodeId: string, quote: string) => {
    setPendingHighlight({ nodeId, quote })
    setTab('run')
    onNavigate(runPathname(scope.projectId, scope.workflowId, scope.runId, nodeId))
  }, [onNavigate, scope])
  const openFile = useCallback((nodeId: string, path: string) => {
    setPendingFile({ nodeId, path })
    setTab('run')
    onNavigate(runPathname(scope.projectId, scope.workflowId, scope.runId, nodeId))
  }, [onNavigate, scope])
  const definitionChanged = current !== null && current.definition_revision !== definition.definition_revision

  const onTabKey = (event: KeyboardEvent<HTMLButtonElement>) => {
    const index = TABS.findIndex(candidate => candidate.id === tab)
    let next: number | null = null
    if (event.key === 'ArrowRight' || event.key === 'ArrowDown') next = (index + 1) % TABS.length
    else if (event.key === 'ArrowLeft' || event.key === 'ArrowUp') next = (index - 1 + TABS.length) % TABS.length
    else if (event.key === 'Home') next = 0
    else if (event.key === 'End') next = TABS.length - 1
    if (next === null) return
    event.preventDefault()
    setTab(TABS[next].id)
    event.currentTarget.parentElement?.querySelector<HTMLButtonElement>(`[data-testid="${TABS[next].testId}"]`)?.focus()
  }

  return (
    <div className="run-view" data-testid="run-view" data-run-id={summary.run_id} data-run-status={summary.status}>
      <section className="run-summary" aria-labelledby="run-summary-title">
        <h2 id="run-summary-title">Run {summary.run_id}</h2>
        <p className="run-status-line" data-testid="run-status">
          <StatusBadge status={summary.status} /> <span data-testid="run-status-meaning">{RUN_STATUS_MEANING[summary.status]}</span>
        </p>
        <dl className="projects-facts">
          <div><dt>Created</dt><dd>{formatTime(summary.created_at)}</dd></div>
          <div><dt>Updated</dt><dd>{formatTime(summary.updated_at)}</dd></div>
          <div><dt>Last event</dt><dd>{snapshot.last_sequence === 0 ? 'none' : `sequence ${snapshot.last_sequence}`}</dd></div>
          <div>
            <dt>Pinned definition</dt>
            <dd data-testid="pinned-definition">
              {definition.name} · revision <code>{shortRevision(definition.definition_revision)}</code>
              {current === null
                ? null
                : definitionChanged
                  ? <span className="projects-warning" data-testid="definition-changed"> — the current workflow definition (revision <code>{shortRevision(current.definition_revision)}</code>) differs; this run is shown against its own pinned graph.</span>
                  : <span className="projects-muted" data-testid="definition-current"> — same as the current workflow definition.</span>}
            </dd>
          </div>
        </dl>
        {(inputs.status === 'loading' || inputs.status === 'idle') && <LoadingPanel>Loading the run inputs…</LoadingPanel>}
        {inputs.status === 'error' && <ErrorPanel error={inputs.error} what="The run inputs" onRetry={reloadInputs} />}
        {inputs.status === 'ready' && inputs.data === null && <p className="projects-muted" data-testid="inputs-none">{INPUTS_NONE_SENTENCE}</p>}
        {inputs.status === 'ready' && inputs.data !== null && (
          <dl className="projects-facts" data-testid="run-inputs-facts">
            <div><dt>Feature</dt><dd>{inputs.data.feature}</dd></div>
            <div><dt>Base commit</dt><dd><code title={inputs.data.base_commit}>{shortRevision(inputs.data.base_commit)}</code></dd></div>
            <div><dt>Source branch</dt><dd>{inputs.data.source_branch === null ? 'None recorded' : <code>{inputs.data.source_branch}</code>}</dd></div>
            <div><dt>Mode</dt><dd>{inputs.data.mode}</dd></div>
            {inputs.data.automatic && (
              <>
                <div><dt>Deadlines</dt><dd>{deadlinesLabel(inputs.data.automatic)}</dd></div>
                <div><dt>Permission mode</dt><dd><code>{inputs.data.automatic.permission_mode}</code></dd></div>
                <div><dt>Finish</dt><dd>{inputs.data.automatic.finish}</dd></div>
              </>
            )}
          </dl>
        )}
      </section>

      <div className="tabs run-tabs" role="tablist" aria-label="Run views">
        {TABS.map(candidate => (
          <button
            key={candidate.id}
            type="button"
            role="tab"
            id={`run-tab-${candidate.id}`}
            className="tab"
            aria-selected={tab === candidate.id}
            aria-controls={`run-panel-${candidate.id}`}
            tabIndex={tab === candidate.id ? 0 : -1}
            data-testid={candidate.testId}
            onClick={() => setTab(candidate.id)}
            onKeyDown={onTabKey}
          >
            {candidate.label}
          </button>
        ))}
      </div>

      {tab === 'assignment' ? (
        <AssignmentPanel scope={scope} inputs={inputs} onRetry={reloadInputs} onNavigate={navigateToNode} panelId="run-panel-assignment" tabId="run-tab-assignment" />
      ) : (
        <div role="tabpanel" id="run-panel-run" aria-labelledby="run-tab-run" className="run-body">
          <section className="run-graph" aria-labelledby="run-graph-title">
            <h3 id="run-graph-title">Pinned graph</h3>
            <WorkflowGraph title={`Pinned definition graph of run ${summary.run_id}`} nodes={graphNodes} selectedId={selectedNodeId} onSelect={selectNode} />
            <p className="projects-muted">Keyboard: Tab or arrow keys move between nodes, Enter or Space opens a node. The list below is the same graph as text.</p>
          </section>

          <div className="run-columns">
            <nav className="run-nodes" aria-labelledby="run-nodes-title">
              <h3 id="run-nodes-title">Nodes</h3>
              <ul className="run-node-list" data-testid="run-node-list">
                {graphNodes.map(node => (
                  <li key={node.node_id} data-node-id={node.node_id} data-status={node.status}>
                    <AppLink href={nodePathname(node.node_id)} onNavigate={onNavigate} className="run-node-link" current={node.node_id === selectedNodeId}>
                      <span className="run-node-label">{node.label}</span>
                      <span className="run-node-meta">
                        <StatusBadge status={node.status!} /> {KIND_LABEL[node.kind]} · attempt {node.attempt}
                      </span>
                    </AppLink>
                  </li>
                ))}
              </ul>
            </nav>

            <div className="run-detail-panel">
              {selectedNodeId === null && (
                <p className="projects-muted" data-testid="node-hint">Select a node in the graph or the list to inspect its attempts, result, evidence and events.</p>
              )}
              {selectedNodeId !== null && (selectedDefinition === null || selectedState === null) && (
                <div className="projects-error" role="alert" data-testid="node-missing">
                  <p>Node <code>{selectedNodeId}</code> is not part of this run's pinned definition.</p>
                  <p><AppLink href={nodePathname()} onNavigate={onNavigate}>Back to the run</AppLink></p>
                </div>
              )}
              {selectedDefinition !== null && selectedState !== null && (
                <NodeDetail
                  key={selectedNodeId}
                  scope={scope}
                  definition={selectedDefinition}
                  definitionNodes={definition.nodes}
                  snapshotNodes={snapshot.nodes}
                  node={selectedState}
                  events={events}
                  onRetryEvents={reloadEvents}
                  inputs={inputs}
                  onRetryInputs={reloadInputs}
                  refreshToken={refreshToken}
                  onNavigate={onNavigate}
                  highlight={highlight}
                  onHighlightApplied={clearHighlight}
                  onOpenRequirement={openRequirement}
                  fileFocus={fileFocus}
                  onFileFocusApplied={clearFile}
                  onOpenFile={openFile}
                />
              )}
            </div>
          </div>
        </div>
      )}
      <p className="projects-muted run-footnote">Statuses: {Object.entries(STATUS_LABEL).map(([key, label]) => `${label} (${key})`).join(', ')}. Only a succeeded run is a completed workflow.</p>
    </div>
  )
}
